# semantic-mutant: SM-73959DE4
from __future__ import annotations

import pytest

from llm_router._internal.capabilities.content import normalize_content

pytestmark = pytest.mark.verification_kind("unit")


@pytest.mark.verifies("REQ_MULTIMODAL_CONTENT_NORMALIZATION[revision==2]")
@pytest.mark.parametrize(
    ("value", "type_name"),
    [
        pytest.param(b"", "bytes", id="empty-bytes"),
        pytest.param(b"describe the scene", "bytes", id="bytes"),
        pytest.param(bytearray(), "bytearray", id="empty-bytearray"),
        pytest.param(
            bytearray(b"describe the scene"), "bytearray", id="bytearray"
        ),
    ],
)
def test_binary_top_level_content_is_rejected_as_message_content(
    value: object, type_name: str
) -> None:
    with pytest.raises(
        TypeError, match=rf"^Unsupported message content: {type_name}\.$"
    ):
        normalize_content(value)
